preConditionHook:
// EL, lowercase as the feature register writes it: legHigh = highest(h,
// legLookback)[1] and legLow = lowest(l, legLookback)[1] --
// the previous bar's Highest/Lowest, i.e. the N bars ENDING ONE BAR AGO
// (today's high[1..legLookback]). highest/lowest bottom out in Extremes(),
// which is EL SOURCE: seeded at the first bar of its window, scanning the rest
// with a strict, tolerance-carrying comparison -- so this seeds at high[1] /
// low[1] and scans 2..legLookback with el_gt/el_lt, exactly as
// CloseAbovePriorHighestHigh does.
legHigh = high[1];
legLow = low[1];
for (int i = 2; i <= (int)legLookback; ++i) {
    if (el_gt(high[i], legHigh)) legHigh = high[i];
    if (el_lt(low[i], legLow)) legLow = low[i];
}
